def backfill_agent_vaults(apps, schema_editor):
    """Every agent with a workspace gets its vault, linked to the agent, so the
    people who could open its secrets before this migration still can."""
    Agent = apps.get_model("agents", "Agent")
    Vault = apps.get_model("agents", "Vault")
    VaultLink = apps.get_model("agents", "VaultLink")
    for agent in Agent.objects.filter(workspace__isnull=False, vault__isnull=True):
        vault = Vault.objects.create(workspace_id=agent.workspace_id, kind="agent", name=agent.slug, agent=agent)
        VaultLink.objects.create(vault=vault, kind="agent", agent=agent, role="use")


